1	import React, { useState, useEffect, useCallback, useRef } from 'react';
2	import { useNavigate } from 'react-router-dom';
3	import { listarImpressoras, getKdsItensRestaurante, marcarItemProntoRestaurante, reimprimirItemRestaurante, iniciarPreparoItemRestaurante, voltarStatusItemRestaurante, cancelarItemRestaurante, getMinhaEmpresa, getSalaoComandaDetalhe, editarItemComandaSalao } from '../../services/restauranteService';
4	import { printTicketSetor } from '../../utils/printComanda';
5	import { formatDuracao } from '../../utils/formatDuracao';
6	import { useNotificacaoSonora } from '../../hooks/useNotificacaoSonora';
7	import { useNowTick } from '../../hooks/useNowTick';
8	import Icon from '../../components/AppIcon';
9	
10	// Card por item (não por mesa/comanda) com cronômetro ao vivo — mostra há quanto tempo
11	// o item chegou (aguardando) e, quando em preparo, há quanto tempo está preparando,
12	// pra dar visibilidade do tempo total gasto até ficar pronto.
13	const ItemCard = ({ item, posicao, now, onReimprimir, onIniciarPreparo, onMarcarPronto, onVoltar, onCancelar, onAbrirComanda, onSalvarObservacao }) => {
14	  const enviadoEm = new Date(item.enviado_em).getTime();
15	  const preparandoEm = item.preparando_em ? new Date(item.preparando_em).getTime() : null;
16	  const tempoEspera = (preparandoEm ?? now) - enviadoEm;
17	  const tempoPreparo = preparandoEm ? now - preparandoEm : 0;
18	  const tempoTotal = now - enviadoEm;
19	  const podeAbrirComanda = item.tipo === 'salao' && !!item.numero_comanda;
20	  const podeEditarObs = item.tipo === 'salao';
21	  const [editandoObs, setEditandoObs] = useState(false);
22	  const [obsInput, setObsInput] = useState(item.observacao ?? '');
23	  useEffect(() => { if (!editandoObs) setObsInput(item.observacao ?? ''); }, [item.observacao, editandoObs]);
24	
25	  const salvarObs = () => {
26	    onSalvarObservacao(item, obsInput);
27	    setEditandoObs(false);
28	  };
29	
30	  return (
31	    <div
32	      onClick={podeAbrirComanda ? () => onAbrirComanda(item.order_id) : undefined}
33	      title={podeAbrirComanda ? 'Ver comanda completa' : undefined}
34	      className={`bg-[#1A1A1A] border rounded-2xl overflow-hidden ${podeAbrirComanda ? 'cursor-pointer hover:border-[#FF441F]/60' : ''} ${posicao === 1 ? 'border-yellow-400/70 ring-1 ring-yellow-400/30' : item.status === 'enviado' ? 'border-blue-500/40' : 'border-[#2A2A2A]'}`}>
35	      {item.garcom && (
36	        <div className="bg-white px-4 py-2">
37	          <p className="text-center text-lg font-black text-[#18181B] uppercase tracking-wide">{item.garcom}</p>
38	        </div>
39	      )}
40	      <div className="p-4">
41	      <div className="flex items-start justify-between mb-1 gap-2">
42	        <div className="flex items-start gap-2">
43	          <span className={`w-6 h-6 flex-shrink-0 rounded-lg flex items-center justify-center text-xs font-black mt-0.5 ${posicao === 1 ? 'bg-yellow-400 text-black' : 'bg-[#2A2A2A] text-white'}`}>
44	            {posicao}
45	          </span>
46	          <div className="leading-tight">
47	            <p className="text-xl font-black text-white">Quantidade: {item.quantity}</p>
48	            <p className="text-lg font-bold text-white">Produto: {item.product_name}</p>
49	          </div>
50	        </div>
51	        <button onClick={(e) => { e.stopPropagation(); onReimprimir(item); }}
52	          className="text-[10px] font-bold text-orange-400 border border-orange-500/40 rounded-lg px-2 py-1 hover:bg-orange-500/10 flex items-center gap-1 flex-shrink-0">
53	          <Icon name="Printer" size={11} /> Reimpressão
54	        </button>
55	      </div>
56	      {posicao === 1 && <p className="text-[10px] font-bold text-yellow-400 uppercase tracking-wide mb-1">Próximo da fila</p>}
57	      {editandoObs ? (
58	        <div className="flex items-center gap-1.5 mb-1" onClick={(e) => e.stopPropagation()}>
59	          <input value={obsInput} onChange={(e) => setObsInput(e.target.value)} autoFocus
60	            placeholder="Observação..." className="flex-1 text-xs bg-[#111111] border border-[#3A3A3A] rounded-lg px-2 py-1 text-white focus:outline-none focus:border-[#FF441F]" />
61	          <button onClick={salvarObs} className="text-xs font-bold text-emerald-400">Salvar</button>
62	          <button onClick={() => setEditandoObs(false)} className="text-xs text-[#71717A]">Cancelar</button>
63	        </div>
64	      ) : item.observacao ? (
65	        <p onClick={podeEditarObs ? (e) => { e.stopPropagation(); setEditandoObs(true); } : undefined}
66	          className={`text-sm font-bold text-white bg-blue-600 rounded px-1.5 py-0.5 mb-1 animate-pulse ${podeEditarObs ? 'cursor-pointer' : ''}`}>
67	          Obs: {item.observacao}
68	        </p>
69	      ) : podeEditarObs ? (
70	        <button onClick={(e) => { e.stopPropagation(); setEditandoObs(true); }}
71	          className="flex items-center gap-1 mb-1 text-xs text-[#71717A] hover:text-white">
72	          <Icon name="MessageSquare" size={11} /> Adicionar observação
73	        </button>
74	      ) : null}
75	      <div className="flex items-center gap-2 text-base font-bold text-yellow-400 mb-2">
76	        <Icon name="MapPin" size={14} />
77	        <span>{item.mesa && item.cliente ? `${item.mesa} • ${item.cliente}` : item.mesa ?? item.cliente ?? (item.tipo === 'delivery' ? `Pedido #${item.order_id}` : 'Avulsa')}</span>
78	        {item.numero_comanda && (
79	          <>
80	            <span className="text-[#71717A]">•</span>
81	            <span>Comanda #{item.numero_comanda}</span>
82	          </>
83	        )}
84	        <span className={`ml-auto px-1.5 py-0.5 rounded-full text-[10px] font-bold ${item.tipo === 'delivery' ? 'bg-sky-500/20 text-sky-400' : 'bg-purple-500/20 text-purple-300'}`}>
85	          {item.tipo === 'delivery' ? 'Delivery' : 'Salão'}
86	        </span>
87	      </div>
88	      <div className="flex items-center gap-3 text-[11px] font-mono mb-3">
89	        <span className="flex items-center gap-1 text-blue-400">
90	          <Icon name="Clock" size={11} /> espera {formatDuracao(tempoEspera)}
91	        </span>
92	        {item.status === 'preparando' && (
93	          <span className="flex items-center gap-1 text-orange-400">
94	            <Icon name="Flame" size={11} /> preparo {formatDuracao(tempoPreparo)}
95	          </span>
96	        )}
97	        <span className="ml-auto text-[#71717A]">total {formatDuracao(tempoTotal)}</span>
98	      </div>
99	      <div className="flex gap-2" onClick={(e) => e.stopPropagation()}>
100	        {item.status !== 'enviado' && (
101	          <button onClick={() => onVoltar(item)} title="Desfazer — clicou errado"
102	            className="flex-shrink-0 px-3 py-2 bg-[#2A2A2A] hover:bg-[#3A3A3A] text-white text-xs font-bold rounded-xl flex items-center justify-center gap-1.5">
103	            <Icon name="Undo2" size={13} /> Voltar
104	          </button>
105	        )}
106	        {item.status === 'enviado' ? (
107	          <>
108	            <button onClick={() => onCancelar(item)} title="Cancelar item"
109	              className="flex-shrink-0 px-3 py-2 bg-red-900/40 hover:bg-red-900/60 text-red-400 text-xs font-bold rounded-xl flex items-center justify-center gap-1.5">
110	              <Icon name="X" size={13} /> Cancelar
111	            </button>
112	            <button onClick={() => onIniciarPreparo(item)}
113	              className="flex-1 py-2 bg-blue-600 hover:bg-blue-700 text-white text-xs font-bold rounded-xl flex items-center justify-center gap-1.5">
114	              <Icon name="ChefHat" size={13} /> Iniciar Preparo
115	            </button>
116	          </>
117	        ) : item.status === 'pronto' ? (
118	          <div className="flex-1 py-2 bg-emerald-900/40 text-emerald-400 text-xs font-bold rounded-xl flex items-center justify-center gap-1.5">
119	            <Icon name="Check" size={13} /> {item.entregue_garcom ? 'Entregue pelo garçom' : 'Entregue'}
120	          </div>
121	        ) : (
122	          <button onClick={() => onMarcarPronto(item.id)}
123	            className="flex-1 py-2 bg-emerald-600 hover:bg-emerald-700 text-white text-xs font-bold rounded-xl flex items-center justify-center gap-1.5">
124	            <Icon name="Check" size={13} /> Pronto
125	          </button>
126	        )}
127	      </div>
128	      </div>
129	    </div>
130	  );
131	};
132	
133	const fmt = (v) => new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(v ?? 0);
134	
135	// Clique no card (só itens de Salão, com numero_comanda) abre essa comanda completa —
136	// mesmo endpoint que o PDV do Salão usa, só leitura aqui (sem ações de pagamento).
137	const ComandaModal = ({ orderId, onFechar }) => {
138	  const [comanda, setComanda] = useState(null);
139	  const [erro, setErro] = useState(null);
140	
141	  useEffect(() => {
142	    getSalaoComandaDetalhe(orderId).then(setComanda).catch((e) => setErro(e.message));
143	  }, [orderId]);
144	
145	  return (
146	    <div className="fixed inset-0 bg-black/70 z-50 flex items-center justify-center p-4" onClick={onFechar}>
147	      <div className="bg-[#1A1A1A] border border-[#2A2A2A] rounded-2xl w-full max-w-md max-h-[85vh] overflow-y-auto" onClick={(e) => e.stopPropagation()}>
148	        <div className="flex items-center justify-between px-4 py-3 border-b border-[#2A2A2A] sticky top-0 bg-[#1A1A1A]">
149	          <h2 className="text-sm font-black text-white">
150	            Comanda {comanda?.numero_comanda ? `#${comanda.numero_comanda}` : ''}
151	          </h2>
152	          <button onClick={onFechar} className="p-1 text-[#71717A] hover:text-white"><Icon name="X" size={18} /></button>
153	        </div>
154	        <div className="p-4">
155	          {erro && <p className="text-sm text-red-400">{erro}</p>}
156	          {!comanda && !erro && <p className="text-sm text-[#71717A]">Carregando...</p>}
157	          {comanda && (
158	            <>
159	              <p className="text-xs text-[#71717A] mb-3">
160	                {comanda.mesas ? `Mesa ${comanda.mesas.numero}${comanda.mesas.nome ? ' - ' + comanda.mesas.nome : ''}` : comanda.cliente_mesa_nome}
161	                {comanda.garcons?.nome && ` • Garçom: ${comanda.garcons.nome}`}
162	                {comanda.aberto_por_nome && ` • Aberto por: ${comanda.aberto_por_nome}`}
163	              </p>
164	              <div className="space-y-2 mb-3">
165	                {(comanda.itens ?? []).map((item) => (
166	                  <div key={item.id} className="flex items-center justify-between gap-2 bg-[#111111] rounded-lg px-3 py-2">
167	                    <div>
168	                      <p className="text-sm font-bold text-white">{item.quantity}x {item.products?.name}</p>
169	                      {item.observacao && <p className="text-xs text-blue-400">Obs: {item.observacao}</p>}
170	                    </div>
171	                    <span className="text-xs text-[#71717A]">{fmt(item.quantity * item.unit_price)}</span>
172	                  </div>
173	                ))}
174	              </div>
175	              <div className="border-t border-[#2A2A2A] pt-3 flex items-center justify-between">
176	                <span className="text-xs font-bold text-[#71717A] uppercase">Total</span>
177	                <span className="text-lg font-black text-white">{fmt(comanda.total)}</span>
178	              </div>
179	            </>
180	          )}
181	        </div>
182	      </div>
183	    </div>
184	  );
185	};
186	
187	// Linha de produção do Salão — visão unificada de TODOS os setores (cozinha, bar,
188	// salgados...) num painel só, dono acessa direto logado (sem link/token separado, mesmo
189	// padrão de acesso da tela de Cozinha do delivery). Cada setor é uma impressora
190	// cadastrada; itens vêm de order_items roteados pra ela (ver GET /restaurante/kds),
191	// lista PLANA por item (não agrupa por mesa/comanda), com cronômetro de espera/preparo.
192	const RestauranteProducao = () => {
193	  const navigate = useNavigate();
194	  const [impressoras, setImpressoras] = useState(null);
195	  const [itensPorImpressora, setItensPorImpressora] = useState({});
196	  const [restauranteNome, setRestauranteNome] = useState('');
197	  const [loading, setLoading] = useState(true);
198	  const [erro, setErro] = useState(null);
199	  const [lastUpdate, setLastUpdate] = useState(null);
200	  const [comandaAbertaId, setComandaAbertaId] = useState(null);
201	  const now = useNowTick();
202	  const [filtroCanal, setFiltroCanal] = useState('todos'); // 'todos' | 'delivery' | 'salao'
203	  const [verTodosEntregues, setVerTodosEntregues] = useState({}); // { [impressoraId]: bool }
204	  const [busca, setBusca] = useState('');
205	  const prevItemIds = useRef(new Set());
206	  const firstLoad = useRef(true);
207	  const tocarSom = useNotificacaoSonora('cozinha');
208	
209	  useEffect(() => {
210	    getMinhaEmpresa().then((d) => setRestauranteNome(d.empresa?.name ?? '')).catch(() => {});
211	    listarImpressoras().then(setImpressoras).catch((e) => setErro(e.message));
212	  }, []);
213	
214	  const carregar = useCallback(async (lista) => {
215	    try {
216	      const resultados = await Promise.all(
217	        lista.map((imp) => getKdsItensRestaurante(imp.id).then((r) => [imp, r.itens ?? []])),
218	      );
219	      const porImpressora = {};
220	      const idsAgora = new Set();
221	      for (const [imp, itens] of resultados) {
222	        porImpressora[imp.id] = itens;
223	        for (const i of itens) idsAgora.add(i.id);
224	      }
225	
226	      if (!firstLoad.current) {
227	        const novos = [...idsAgora].filter((id) => !prevItemIds.current.has(id));
228	        if (novos.length > 0) tocarSom();
229	      } else {
230	        firstLoad.current = false;
231	      }
232	      prevItemIds.current = idsAgora;
233	
234	      setItensPorImpressora(porImpressora);
235	      setLastUpdate(new Date());
236	      setErro(null);
237	    } catch (e) {
238	      setErro(e.message);
239	    } finally {
240	      setLoading(false);
241	    }
242	  }, [tocarSom]);
243	
244	  useEffect(() => {
245	    if (!impressoras) return;
246	    if (impressoras.length === 0) { setLoading(false); return; }
247	    carregar(impressoras);
248	    const interval = setInterval(() => carregar(impressoras), 15000);
249	    return () => clearInterval(interval);
250	  }, [impressoras, carregar]);
251	
252	  const marcarPronto = async (itemId) => {
253	    await marcarItemProntoRestaurante(itemId);
254	    carregar(impressoras);
255	  };
256	
257	  const iniciarPreparo = async (item) => {
258	    await iniciarPreparoItemRestaurante(item.id);
259	    carregar(impressoras);
260	  };
261	
262	  const voltarItem = async (item) => {
263	    await voltarStatusItemRestaurante(item.id);
264	    carregar(impressoras);
265	  };
266	
267	  const cancelarItem = async (item) => {
268	    if (!confirm(`Cancelar "${item.product_name}"? Esta ação não pode ser desfeita.`)) return;
269	    try {
270	      await cancelarItemRestaurante(item.id);
271	      carregar(impressoras);
272	    } catch (e) {
273	      alert(e.message);
274	    }
275	  };
276	
277	  const reimprimir = async (item, setorNome) => {
278	    try {
279	      const res = await reimprimirItemRestaurante(item.id);
280	      if (res.via === 'navegador') {
281	        printTicketSetor([item], { mesaLabel: item.mesa, cliente_mesa_nome: item.cliente }, setorNome);
282	      }
283	    } catch (e) {
284	      setErro(e.message);
285	    }
286	  };
287	
288	  const salvarObservacao = async (item, observacao) => {
289	    try {
290	      await editarItemComandaSalao(item.order_id, item.id, { observacao });
291	      carregar(impressoras);
292	    } catch (e) {
293	      setErro(e.message);
294	    }
295	  };
296	
297	  if (loading) return (
298	    <div className="min-h-screen bg-[#111111] flex items-center justify-center">
299	      <div className="w-10 h-10 border-4 border-[#FF441F] border-t-transparent rounded-full animate-spin" />
300	    </div>
301	  );
302	
303	  const todosItens = Object.values(itensPorImpressora).flat();
304	  const totalDelivery = todosItens.filter((i) => i.tipo === 'delivery').length;
305	  const totalSalao = todosItens.filter((i) => i.tipo === 'salao').length;
306	  const buscaNormalizada = busca.trim().toLowerCase();
307	  const passaBusca = (i) => {
308	    if (!buscaNormalizada) return true;
309	    const alvo = [i.cliente, i.mesa, i.mesa_numero, i.numero_comanda, i.garcom]
310	      .filter((v) => v !== null && v !== undefined)
311	      .join(' ')
312	      .toLowerCase();
313	    return alvo.includes(buscaNormalizada);
314	  };
315	  const passaFiltro = (i) => (filtroCanal === 'todos' || i.tipo === filtroCanal) && passaBusca(i);
316	  const totalItens = todosItens.filter(passaFiltro).length;
317	
318	  return (
319	    <div className="min-h-screen bg-[#111111]">
320	      <header className="bg-[#1A1A1A] border-b border-[#2A2A2A] px-5 py-3">
321	        <div className="flex items-center gap-4">
322	          <button onClick={() => navigate('/restaurante')} className="p-2 text-[#71717A] hover:text-white rounded-lg hover:bg-[#2A2A2A]">
323	            <Icon name="ArrowLeft" size={18} />
324	          </button>
325	          <div className="flex items-center gap-2">
326	            <div className="w-8 h-8 bg-[#FF441F] rounded-lg flex items-center justify-center flex-shrink-0">
327	              <Icon name="ChefHat" size={16} className="text-white" />
328	            </div>
329	            <div>
330	              <p className="text-white font-black text-base leading-none">Linha de Produção — Salão</p>
331	              <p className="text-[#71717A] text-xs">{restauranteNome}</p>
332	            </div>
333	          </div>
334	          <div className="ml-auto flex items-center gap-2">
335	            <div className="flex items-center gap-2 text-xs text-[#71717A]">
336	              <span className="w-1.5 h-1.5 rounded-full bg-green-500 animate-pulse" />
337	              {lastUpdate?.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' }) ?? '—'}
338	            </div>
339	            <button onClick={() => carregar(impressoras ?? [])} className="p-2 text-[#71717A] hover:text-white rounded-lg hover:bg-[#2A2A2A]">
340	              <Icon name="RefreshCw" size={16} />
341	            </button>
342	          </div>
343	        </div>
344	
345	        {/* Busca por cliente, mesa, comanda ou garçom */}
346	        <div className="flex items-center gap-2 mt-3 px-3 py-2 rounded-xl border border-[#2A2A2A] bg-[#111111] focus-within:border-[#FF441F]">
347	          <Icon name="Search" size={16} className="text-[#71717A] flex-shrink-0" />
348	          <input
349	            type="text"
350	            value={busca}
351	            onChange={(e) => setBusca(e.target.value)}
352	            placeholder="Buscar por cliente, mesa, comanda ou garçom..."
353	            className="flex-1 bg-transparent text-white text-sm placeholder:text-[#3A3A3A] outline-none"
354	          />
355	          {busca && (
356	            <button onClick={() => setBusca('')} className="text-[#71717A] hover:text-white flex-shrink-0">
357	              <Icon name="X" size={15} />
358	            </button>
359	          )}
360	        </div>
361	
362	        {/* Filtro de canal — Todos/Delivery/Salão */}
363	        <div className="flex items-center gap-2 mt-3">
364	          {[
365	            { key: 'todos', label: 'Todos', count: totalDelivery + totalSalao },
366	            { key: 'delivery', label: 'Delivery', count: totalDelivery },
367	            { key: 'salao', label: 'Salão', count: totalSalao },
368	          ].map((f) => (
369	            <button
370	              key={f.key}
371	              onClick={() => setFiltroCanal(f.key)}
372	              className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-bold transition-colors ${
373	                filtroCanal === f.key
374	                  ? 'bg-[#FF441F] text-white'
375	                  : 'bg-[#111111] text-[#71717A] border border-[#2A2A2A] hover:text-white'
376	              }`}
377	            >
378	              {f.label}
379	              <span className={`px-1.5 py-0.5 rounded-full text-[10px] ${filtroCanal === f.key ? 'bg-white/20' : 'bg-[#2A2A2A]'}`}>{f.count}</span>
380	            </button>
381	          ))}
382	        </div>
383	      </header>
384	
385	      {erro && (
386	        <div className="mx-5 mt-4 bg-red-900/50 border border-red-700 rounded-xl px-4 py-3 text-sm text-red-400">{erro}</div>
387	      )}
388	
389	      {impressoras && impressoras.length === 0 ? (
390	        <div className="text-center py-20 px-5">
391	          <Icon name="Printer" size={48} className="text-[#2A2A2A] mx-auto mb-4" />
392	          <p className="text-[#71717A] text-lg font-semibold">Nenhuma impressora cadastrada</p>
393	          <p className="text-[#3A3A3A] text-sm mt-1">Cada setor (Cozinha, Bar, Salgados...) precisa de uma impressora cadastrada com esse setor.</p>
394	          <button onClick={() => navigate('/restaurante/impressoras')}
395	            className="mt-4 px-4 py-2 bg-[#FF441F] text-white text-sm font-bold rounded-xl hover:bg-[#E63A19]">
396	            Ir pra Impressoras
397	          </button>
398	        </div>
399	      ) : (
400	        <main className="p-5 max-w-6xl mx-auto space-y-8">
401	          {(impressoras ?? []).map((imp) => {
402	            const itens = (itensPorImpressora[imp.id] ?? []).filter(passaFiltro);
403	            const aguardando = itens.filter((i) => i.status === 'enviado');
404	            const preparando = itens.filter((i) => i.status === 'preparando');
405	            const entregues = itens
